steps.action:
curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{
      users(includeInactive: true, first: 50) {
        nodes {
          id
          name
          emailAddress
        }
      }
      issue(identifier: \"ENG-5\") {
        id
        identifier
        title
        assignee {
          id
          name
        }
      }
    }"
  }'
